// Generated by packages/retroplug/scripts/lib/packages.mjs from the desktop product's package list and the
// packages' manifests. Do not edit; edit a manifest and rebuild.
//
// The script-node bundle's entry: each contribution kind's runtime halves (the manifests' protocol.kinds
// entries, registered by the declaring package), then every package's protocol node definitions, in span-label
// order (spec/08-profiling.md: one label a type, 16 up), which the manifests' retroplug.protocol.nodes fix
// whatever order a package lists its exports in. esbuilt to a global-code IIFE, compiled to QuickJS bytecode
// and embedded by each product (packages/native/cmake/bundles.cmake), so every Engine loads it into both of
// its script contexts.
import type { DefinedNode } from "@retroplug/core/defineNode";
import { registerScriptNodes } from "@retroplug/core/register";
import nodes_alpha from "@retroplug/alpha/nodes";
import nodes_retroplug from "../script/nodes";
import { registerWidgets } from "@retroplug/alpha/widgets";
import { registerControllerApps, type ControllerAppRuntime } from "@retroplug/beta/apps";
import item_controllerApps_alpha_alpha_app from "@retroplug/alpha/appRuntime";

// The host numbers the nodes it is handed from the first protocol span label up (spec/08-profiling.md).
const FIRST_LABEL = 16;

// The span label of each node type the product's manifests declare.
const LABELS: Readonly<Record<string, number | undefined>> = {
  "rp.alpha.midi": 16,
  "rp.fixture.shell": 17,
};

function labelOf(node: DefinedNode<any>): number {
  const label = LABELS[node.id];
  if (label === undefined) {
    throw new Error(`the script node ${node.id} has no span label (a package's retroplug.protocol.nodes)`);
  }
  return label;
}

// Each package's definitions, in product order; the order the bundle registers them in is the labels', below.
const lists: readonly (readonly DefinedNode<any>[])[] = [
  nodes_alpha,
  nodes_retroplug,
];

const nodes: DefinedNode<any>[] = [];
for (const list of lists) for (const node of list) nodes.push(node);
nodes.sort((a, b) => labelOf(a) - labelOf(b));

// A label is not a node's own: the host numbers what it is handed, in order (ScriptHost's spanLabelFor), so a
// manifest node its module does not export would shift every later type one label down, and a node no manifest
// declares would take the label of one that is missing. Refuse the bundle unless what the modules define is
// exactly the manifests' declarations, each at its own label.
const declared = Object.keys(LABELS);
const missing = declared.filter((type) => !nodes.some((node) => node.id === type));
const extra = nodes.filter((node) => LABELS[node.id] === undefined).map((node) => node.id);
if (missing.length || extra.length) {
  throw new Error(
    `the script bundle's nodes are not the manifests': ${nodes.length} defined, ${declared.length} declared; ` +
      (missing.length
        ? `${missing.join(", ")} has no definition`
        : `${extra.join(", ")} is declared by no manifest`),
  );
}
for (let i = 0; i < nodes.length; i++) {
  if (labelOf(nodes[i]) !== FIRST_LABEL + i) {
    throw new Error(
      `the script node ${nodes[i].id} would take the span label ${FIRST_LABEL + i}, ` +
        `not its ${labelOf(nodes[i])}`,
    );
  }
}

// The controllerApps items' runtimes, in product order: the manifests' protocol.kinds.controllerApps. Each import is one
// manifest entry's module, so the check is per entry: a module that registers another id would leave a
// document naming an item nothing runs, and the message names the module and both ids rather than a set
// difference.
const kindItems_controllerApps: readonly ControllerAppRuntime[] = [
  item_controllerApps_alpha_alpha_app,
];
const kindModules_controllerApps: readonly string[] = [
  "item_controllerApps_alpha_alpha_app",
];
const kindIds_controllerApps: readonly string[] = [
  "alpha-app",
];
for (let i = 0; i < kindItems_controllerApps.length; i++) {
  if (kindItems_controllerApps[i].id !== kindIds_controllerApps[i]) {
    throw new Error(
      `the script bundle's controllerApps item ${kindModules_controllerApps[i]} registers ${kindItems_controllerApps[i].id}, but its manifest entry declares ${kindIds_controllerApps[i]}`
    );
  }
}
registerControllerApps(kindItems_controllerApps);

registerScriptNodes(nodes);

// A downloaded pack's kind items register their runtimes through this, after the product's own above
// (docs/downloadable-packs-m2f-plan.md): its kinds half runs it in both of the built-in pack's contexts. It
// refuses a kind this product does not declare, items that are not the ids the pack's manifest declares, and an
// id the kind already holds, which the kind's own register would replace without a word.
const KIND_REGISTRARS: Record<string, { register: (items: readonly any[]) => void; owners: Record<string, string> }> = {
  "widgets": { register: registerWidgets, owners: Object.assign(Object.create(null), {}) },
  "controllerApps": { register: registerControllerApps, owners: Object.assign(Object.create(null), {"alpha-app":"alpha"}) },
};
// The Engine closes it once it has loaded the packs' kinds halves, so a reference a pack kept refuses too.
let kindRegistrarClosed = false;
(globalThis as Record<string, unknown>).__rp_closeKindRegistrar = (): void => {
  kindRegistrarClosed = true;
};
(globalThis as Record<string, unknown>).__rp_registerKindItems = (
  kind: string, items: readonly { id: string }[], ids: readonly string[],
): void => {
  if (kindRegistrarClosed) {
    throw new Error("the kind registrar is closed: a pack's kind items join an Engine only at its construction");
  }
  const entry = Object.prototype.hasOwnProperty.call(KIND_REGISTRARS, kind) ? KIND_REGISTRARS[kind] : undefined;
  if (!entry) throw new Error(`a pack's kinds half registers items of ${kind}, a contribution kind this product does not declare`);
  if (!Array.isArray(items) || !Array.isArray(ids)) {
    throw new Error(`a pack's kinds half registers ${kind} with items and ids that are not lists`);
  }
  const got: string[] = [];
  for (const item of items) {
    if (typeof item !== "object" || item === null || typeof item.id !== "string") {
      throw new Error(`a pack's kinds half registers a ${kind} item that is not an object with a string id`);
    }
    got.push(item.id);
  }
  if (got.length !== ids.length || got.some((id, i) => id !== ids[i])) {
    throw new Error(`a pack's kinds half registers the ${kind} items ${got.join(", ")}, and its manifest declares ${ids.join(", ")}`);
  }
  for (let i = 0; i < got.length; i++) {
    const id = got[i];
    if (got.indexOf(id) !== i) throw new Error(`a pack's kinds half registers the ${kind} item ${id} twice`);
    const owner = entry.owners[id];
    if (owner !== undefined) {
      throw new Error(`a pack's kinds half registers the ${kind} item ${id}, which ${owner === "" ? "an earlier pack" : `this product's ${owner}`} holds`);
    }
  }
  for (const id of got) entry.owners[id] = "";
  entry.register(items);
};
